41	/* Generic validation
42	 *
43	 * [--type--][--len---]
44	 *
45	 * \todo This function needs removed in favor of specific validation.
46	 *
47	 * See: RFC 791
48	 */
49	static int IPV4OptValidateGeneric(Packet *p, const IPV4Opt *o)
50	{
51	    switch (o->type) {
52	        /* See: RFC 4782 */
53	        case IPV4_OPT_QS:
54	            if (o->len < IPV4_OPT_QS_MIN) {
55	                ENGINE_SET_INVALID_EVENT(p, IPV4_OPT_INVALID_LEN);
56	                return -1;
57	            }
58	            break;
59	        /* See: RFC 1108 */
60	        case IPV4_OPT_SEC:
61	        case IPV4_OPT_ESEC:
62	            if (unlikely(o->len < IPV4_OPT_SEC_MIN)) {
63	                ENGINE_SET_INVALID_EVENT(p, IPV4_OPT_INVALID_LEN);
64	                return -1;
65	            }
66	            break;
67	        case IPV4_OPT_SID:
68	            if (o->len != IPV4_OPT_SID_LEN) {
69	                ENGINE_SET_INVALID_EVENT(p, IPV4_OPT_INVALID_LEN);
70	                return -1;
71	            }
72	            break;
73	        /* See: RFC 2113 */
74	        case IPV4_OPT_RTRALT:
75	            if (o->len != IPV4_OPT_RTRALT_LEN) {
76	                ENGINE_SET_INVALID_EVENT(p, IPV4_OPT_INVALID_LEN);
77	                return -1;
78	            }
79	            break;
80	        default:
81	            /* Should never get here unless there is a coding error */
82	            ENGINE_SET_INVALID_EVENT(p, IPV4_OPT_UNKNOWN);
83	            return -1;
84	    }
85	
86	    return 0;
87	}
