280	typedef struct IPV4Options_ {
281	    IPV4Opt o_rr;
282	    IPV4Opt o_qs;
283	    IPV4Opt o_ts;
284	    IPV4Opt o_sec;
285	    IPV4Opt o_lsrr;
286	    IPV4Opt o_esec;
287	    IPV4Opt o_cipso;
