    FAIL_IF(!(p->flags & PKT_WANTS_FLOW));
    PacketRecycle(p);

    PacketCopyData(p, pkt1, sizeof(pkt1));
    DecodeIPV4(&tv, &dtv, p, GET_PKT_DATA(p) + ETHERNET_HEADER_LEN,
